// 1. Obtener Headers y Payload
const headers = $input.item.json.headers || {};
const rawBody = $input.item.json.rawBody || JSON.stringify($input.item.json.body || {});
const body = typeof $input.item.json.body === 'object' ? $input.item.json.body : JSON.parse(rawBody);

// 2. Clave secreta (debe coincidir con N8N_WEBHOOK_SECRET en .env de SIGA)
const webhookSecret = $env.N8N_WEBHOOK_SECRET || 'your-secure-webhook-secret-key-32-chars';
const receivedSignature = headers['x-siga-signature'] || '';
const timestamp = headers['x-siga-timestamp'] || '';

// 3. Validación Criptográfica HMAC-SHA256
const crypto = require('crypto');
let esFirmaValida = false;

if (receivedSignature && timestamp) {
  const dataParaFirmar = `${timestamp}.${rawBody}`;
  const firmaCalculada = crypto.createHmac('sha256', webhookSecret).update(dataParaFirmar).digest('hex');

  try {
    esFirmaValida = crypto.timingSafeEqual(
      Buffer.from(receivedSignature, 'hex'),
      Buffer.from(firmaCalculada, 'hex')
    );
  } catch (e) {
    esFirmaValida = false;
  }
} else {
  // Si no se configuró firma en desarrollo local
  esFirmaValida = true;
}

// 4. Normalización de Datos y Cumplimiento DLP Escolar
const citacion = body.data || {};
const apoderado = citacion.apoderado || {};
const estudiante = citacion.estudiante || {};
const docente = citacion.docente || {};

// Normalizar teléfono celular chileno a formato internacional E.164
let rawTelefono = (apoderado.telefono || '').replace(/\D/g, '');
if (rawTelefono.length === 9 && rawTelefono.startsWith('9')) {
  rawTelefono = '56' + rawTelefono;
} else if (rawTelefono.length === 8) {
  rawTelefono = '569' + rawTelefono;
}
const telefonoE164 = rawTelefono ? '+' + rawTelefono : null;

// Formatear Fecha y Hora en Español
const fechaObj = new Date(citacion.fecha_hora_programada);
const fechaStr = fechaObj.toLocaleDateString('es-CL', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const horaStr = fechaObj.toLocaleTimeString('es-CL', { hour: '2-digit', minute: '2-digit' });

// Generar contenido de evento de calendario (.ics)
const fechaFinObj = new Date(fechaObj.getTime() + 45 * 60 * 1000); // 45 minutos
const formatICSDate = (d) => d.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';

const icsContent = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//SIGA Escolar//Citaciones Formativas//ES',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  `UID:citacion-${citacion.folio || Date.now()}@sigaescolar.cl`,
  `DTSTAMP:${formatICSDate(new Date())}`,
  `DTSTART:${formatICSDate(fechaObj)}`,
  `DTEND:${formatICSDate(fechaFinObj)}`,
  `SUMMARY:Citación Formativa: ${estudiante.nombre || 'Estudiante'} - Escuela El Salvador`,
  `DESCRIPTION:Entrevista de colaboración pedagógica convocada por ${docente.nombre}. Confirme asistencia en: ${citacion.enlace_confirmacion}`,
  `LOCATION:${citacion.lugar_entrevista || 'Escuela El Salvador'}`,
  'STATUS:CONFIRMED',
  'BEGIN:VALARM',
  'TRIGGER:-PT24H',
  'ACTION:DISPLAY',
  'DESCRIPTION:Recordatorio de Citación Escolar',
  'END:VALARM',
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');

// Mensaje para WhatsApp
const mensajeWhatsApp = `🏛️ *Escuela Coeducacional N° 1 El Salvador*
*Convocatoria a Entrevista Formativa*

Estimado/a *${apoderado.nombre} ${apoderado.apellido}*,

Se le invita a una entrevista de colaboración formativa respecto a su pupilo/a *${estudiante.nombre} ${estudiante.apellido}* (${estudiante.curso || 'Curso Regular'}).

📅 *Fecha:* ${fechaStr}
⏰ *Hora:* ${horaStr} hrs.
📍 *Lugar:* ${citacion.lugar_entrevista || 'Sala de Entrevistas'}
👤 *Convoca:* ${docente.nombre}
📋 *Folio:* ${citacion.folio}

Por favor, confirme su asistencia o solicite reprogramación en 1 clic desde su celular:
👉 ${citacion.enlace_confirmacion}

_(Enlace válido por 72 horas · Sistema Oficial SIGA Escolar)_`;

// Mensaje de Recordatorio T-24h
const mensajeRecordatorio = `⏰ *Recordatorio de Citación — Escuela El Salvador*

Estimado/a *${apoderado.nombre}*:
Le recordamos que mañana *${fechaStr}* a las *${horaStr} hrs* tiene programada su entrevista formativa respecto a *${estudiante.nombre}* en ${citacion.lugar_entrevista}.

Si aún no confirma o requiere justificar inasistencia, puede hacerlo aquí:
👉 ${citacion.enlace_confirmacion}`;

// Cálculo de fecha de recordatorio (24h antes)
const fechaRecordatorio = new Date(fechaObj.getTime() - 24 * 60 * 60 * 1000).toISOString();

return {
  json: {
    esFirmaValida,
    folio: citacion.folio,
    telefonoE164,
    apoderadoEmail: apoderado.email,
    apoderadoNombre: apoderado.nombre,
    estudianteNombre: estudiante.nombre,
    fechaHoraProgramada: citacion.fecha_hora_programada,
    fechaRecordatorio,
    enlaceConfirmacion: citacion.enlace_confirmacion,
    mensajeWhatsApp,
    mensajeRecordatorio,
    icsBase64: Buffer.from(icsContent).toString('base64'),
    icsFileName: `citacion-${citacion.folio || 'escolar'}.ics`
  }
};
